<?php
namespace Modules\Glitter\NotificationHub\Tests\Unit\Services\Admin;
use Illuminate\Contracts\Pagination\LengthAwarePaginator;use Modules\Glitter\NotificationHub\Contracts\NotificationHubInterface;use Modules\Glitter\NotificationHub\Contracts\Repositories\AttemptRepositoryInterface;use Modules\Glitter\NotificationHub\Contracts\Repositories\DeadLetterRepositoryInterface;use Modules\Glitter\NotificationHub\Contracts\Repositories\NotificationHubTransactionInterface;use Modules\Glitter\NotificationHub\Contracts\Repositories\PlanRepositoryInterface;use Modules\Glitter\NotificationHub\DTO\Admin\ManualRetryData;use Modules\Glitter\NotificationHub\DTO\Admin\NotificationPlanSearchData;use Modules\Glitter\NotificationHub\DTO\NotificationResultData;use Modules\Glitter\NotificationHub\Enums\PlanStatus;use Modules\Glitter\NotificationHub\Enums\RetryPolicy;use Modules\Glitter\NotificationHub\Exceptions\AdminActionConflictException;use Modules\Glitter\NotificationHub\Models\NotificationDeadLetter;use Modules\Glitter\NotificationHub\Models\NotificationPlan;use Modules\Glitter\NotificationHub\Services\Admin\NotificationHubAdminService;use Modules\Glitter\NotificationHub\Services\PlanStateTransitionService;use Modules\Glitter\NotificationHub\Support\DeliveryMetadataSanitizer;use PHPUnit\Framework\TestCase;use ReflectionMethod;
class NotificationHubAdminServiceTest extends TestCase
{
 public function test_plan_search_dto_is_forwarded_without_dispatch():void{$search=NotificationPlanSearchData::fromArray(['status'=>'failed']);$page=$this->createMock(LengthAwarePaginator::class);$plans=$this->createMock(PlanRepositoryInterface::class);$plans->expects($this->once())->method('paginateForAdmin')->with($search)->willReturn($page);$hub=$this->createMock(NotificationHubInterface::class);$hub->expects($this->never())->method('createPlan');$service=new NotificationHubAdminService($plans,$this->createMock(AttemptRepositoryInterface::class),$this->createMock(DeadLetterRepositoryInterface::class),$hub,$this->createMock(PlanStateTransitionService::class),new DeliveryMetadataSanitizer,$this->createMock(NotificationHubTransactionInterface::class));$this->assertSame($page,$service->listPlans($search));}
 public function test_admin_surface_has_no_dispatch_method():void{$methods=array_map(fn($m)=>$m->getName(),(new \ReflectionClass(NotificationHubAdminService::class))->getMethods(ReflectionMethod::IS_PUBLIC));$this->assertContains('retryPlan',$methods);$this->assertNotContains('dispatch',$methods);$this->assertNotContains('notify',$methods);}
 public function test_request_id_is_reused_or_generated_per_request():void{$reflection=new \ReflectionClass(NotificationHubAdminService::class);$service=$reflection->newInstanceWithoutConstructor();$method=$reflection->getMethod('withRequestId');$provided='00000000-0000-4000-8000-000000000001';$base=fn(?string $id)=>new ManualRetryData($id,'reason',null,RetryPolicy::None,1,null);$this->assertSame($provided,$method->invoke($service,$base($provided))->requestId);$first=$method->invoke($service,$base(null))->requestId;$second=$method->invoke($service,$base(null))->requestId;$this->assertMatchesRegularExpression('/^[0-9a-f-]{36}$/',$first);$this->assertNotSame($first,$second);}
 public function test_resolved_dead_letter_replay_with_same_request_id_converges_without_creation():void{$requestId='00000000-0000-4000-8000-000000000001';$dead=new NotificationDeadLetter(['plan_id'=>'original','resolved_at'=>'2026-08-02 00:00:00']);$dead->id='dead';$original=$this->plan('original',PlanStatus::Failed);$existing=$this->plan('new',PlanStatus::Pending);$existing->retry_of_plan_id='original';$plans=$this->createMock(PlanRepositoryInterface::class);$plans->method('findById')->willReturnMap([['original',$original]]);$plans->expects($this->once())->method('findDuplicate')->willReturn($existing);$deadLetters=$this->createMock(DeadLetterRepositoryInterface::class);$deadLetters->method('findByIdForUpdate')->willReturn($dead);$deadLetters->expects($this->never())->method('resolve');$hub=$this->createMock(NotificationHubInterface::class);$hub->expects($this->never())->method('createPlan');$result=$this->service($plans,$deadLetters,$hub)->retryDeadLetter('dead',new ManualRetryData($requestId,'reason',null,RetryPolicy::None,1,1));$this->assertSame('new',$result->result->planId);$this->assertTrue($result->result->isDuplicate);$this->assertSame($requestId,$result->requestId);}
 public function test_resolved_dead_letter_with_new_request_id_is_rejected():void{$dead=new NotificationDeadLetter(['plan_id'=>'original','resolved_at'=>'2026-08-02 00:00:00']);$dead->id='dead';$plans=$this->createMock(PlanRepositoryInterface::class);$plans->method('findById')->willReturn($this->plan('original',PlanStatus::Failed));$plans->method('findDuplicate')->willReturn(null);$deadLetters=$this->createMock(DeadLetterRepositoryInterface::class);$deadLetters->method('findByIdForUpdate')->willReturn($dead);$hub=$this->createMock(NotificationHubInterface::class);$hub->expects($this->never())->method('createPlan');$this->expectException(AdminActionConflictException::class);$this->service($plans,$deadLetters,$hub)->retryDeadLetter('dead',new ManualRetryData('00000000-0000-4000-8000-000000000002','reason',null,RetryPolicy::None,1,1));}
 private function service(PlanRepositoryInterface $plans,DeadLetterRepositoryInterface $deadLetters,NotificationHubInterface $hub):NotificationHubAdminService{$transaction=$this->createMock(NotificationHubTransactionInterface::class);$transaction->method('run')->willReturnCallback(fn($callback)=>$callback());return new NotificationHubAdminService($plans,$this->createMock(AttemptRepositoryInterface::class),$deadLetters,$hub,$this->createMock(PlanStateTransitionService::class),new DeliveryMetadataSanitizer,$transaction);}
 private function plan(string $id,PlanStatus $status):NotificationPlan{$plan=new NotificationPlan(['status'=>$status,'definition_type'=>'type','hook_prefix'=>'hook','extension_type'=>'module','extension_identifier'=>'module','recipient_type'=>'user','recipient_id'=>1,'recipient_snapshot'=>[],'channel'=>'mail','data'=>[],'context'=>[],'policy_snapshot'=>[],'retry_policy'=>RetryPolicy::None,'max_attempts'=>1]);$plan->id=$id;$plan->correlation_id='correlation-'.$id;return $plan;}
}
